<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\FinancialTransaction; use App\Models\Order; use Illuminate\Http\Request;
class AdminFinanceReportController extends Controller { public function __invoke(Request $r) { $d=$r->validate(['from'=>['nullable','date'],'to'=>['nullable','date']]); $o=Order::query(); $f=FinancialTransaction::query(); foreach([$o,$f] as $q){if($d['from']??null)$q->whereDate('created_at','>=',$d['from']);if($d['to']??null)$q->whereDate('created_at','<=',$d['to']);} $gross=(clone $o)->whereIn('status',['paid','processing','packed','shipped','completed'])->sum('subtotal'); $discount=(clone $o)->sum('discount_total'); $shipping=(clone $o)->sum('shipping_total'); $income=(clone $f)->where('type','income')->sum('amount'); $expense=(clone $f)->where('type','expense')->sum('amount'); $refund=(clone $f)->where('type','refund')->sum('amount'); return response()->json(['data'=>['gross_sales'=>$gross,'discount'=>$discount,'net_sales'=>$gross-$discount,'shipping'=>$shipping,'refund'=>$refund,'expenses'=>$expense,'cash_flow'=>$income-$expense-$refund]]); } }
